assert 'NUMBER' in '
<!DOCTYPE html>
<html lang="en" class="h-full">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>WhatsApp Leads | Elvis-Manager</title>

    <!-- Tailwind CSS -->
    <script src="https://cdn.tailwindcss.com"></script>
    <script>
        tailwind.config = {
            theme: {
                extend: {
                    colors: {
                        primary: {
                            50: '#fef2f2',
                            100: '#fee2e2',
                            200: '#fecaca',
                            300: '#fca5a5',
                            400: '#f87171',
                            500: '#AE1F25',
                            600: '#9B1B21',
                            700: '#87171C',
                            800: '#731318',
                            900: '#5F0F14'
                        },
                        sidebar: {
                            DEFAULT: '#000000',
                            hover: '#1a1a1a',
                            active: '#2d2d2d'
                        },
                        ...uccess: 'fa-check-circle',
                error: 'fa-exclamation-circle',
                warning: 'fa-exclamation-triangle',
                info: 'fa-info-circle'
            };
            const toast = document.createElement('div');
            toast.className = `flex items-center p-4 rounded-xl animate-fade-in border ${colors[type]}`;
            toast.innerHTML = `
                <i class="fas ${icons[type]} mr-3 text-lg"></i>
                <span class="flex-1 text-base font-medium">${message}</span>
                <button onclick="this.parentElement.remove()" class="ml-4 hover:opacity-70"><i class="fas fa-times"></i></button>
            `;
            container.appendChild(toast);
            setTimeout(() => toast.remove(), 5000);
        }

        function createToastContainer() {
            const container = document.createElement('div');
            container.setAttribute('data-testid', 'messages-container');
            container.className = 'fixed top-24 right-8 z-50 space-y-3 w-96';
            document.body.appendChild(container);
            return container;
        }
    </script>

</body>
</html>
'

